+const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
+
+// Returns the canonical YYYY-MM-DD string when valid, otherwise null.
+function parseISODate(value) {
+  if (typeof value !== 'string') return null;
+  const m = ISO_DATE.exec(value);
+  if (!m) return null;
+  const y = Number(m[1]);
+  const mo = Number(m[2]);
+  const d = Number(m[3]);
+  const dt = new Date(Date.UTC(y, mo - 1, d));
+  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) {
+    return null;
+  }
+  return value;
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'sales_report',
+      description:
+        'Sum sales rows within an inclusive ISO date range (YYYY-MM-DD) and report the total amount and row count.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          start_date: { type: 'string', description: 'Inclusive start date as YYYY-MM-DD.' },
+          end_date: { type: 'string', description: 'Inclusive end date as YYYY-MM-DD.' }
+        },
+        required: ['start_date', 'end_date'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'sales_report') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  const allowed = new Set(['start_date', 'end_date']);
+  for (const key of Object.keys(args)) {
+    if (!allowed.has(key)) {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+
+  const { start_date, end_date } = args;
+  if (start_date === undefined) throw new Error('start_date is required');
+  if (end_date === undefined) throw new Error('end_date is required');
+  if (!parseISODate(start_date)) throw new Error('start_date must be a valid ISO date (YYYY-MM-DD)');
+  if (!parseISODate(end_date)) throw new Error('end_date must be a valid ISO date (YYYY-MM-DD)');
+  if (start_date > end_date) throw new Error('start_date must not be after end_date');
+
+  // ISO YYYY-MM-DD strings compare lexicographically the same as chronologically.
+  let total = 0;
+  let count = 0;
+  for (const row of sales) {
+    if (row.date >= start_date && row.date <= end_date) {
+      total += row.amount;
+      count += 1;
+    }
+  }
